begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(15);
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select is(public.project_summary('20000000-0000-0000-0000-000000000001')->>'cash','9840000','Seed cash is reconciled');
select is(public.project_summary('20000000-0000-0000-0000-000000000001')->>'expense','6620000','Net recognized expenses include bill and advance expense');
select is(public.project_summary('20000000-0000-0000-0000-000000000001')->>'payable','220000','Partial reimbursement leaves entitlement');
select is(public.project_summary('20000000-0000-0000-0000-000000000001')->>'bills','1240000','Unpaid bill leaves payable');
select is(public.project_summary('20000000-0000-0000-0000-000000000001')->>'advances','0','Advance reconciled and returned');
select is(public.project_summary('20000000-0000-0000-0000-000000000001')->>'available','8380000','Available does not double reserve');
select ok(not exists(select 1 from public.ledger_entries group by financial_event_id having sum(case direction when 'DEBIT' then amount_minor else -amount_minor end)<>0),'Every event balances');
select throws_ok('update public.ledger_entries set memo=''tampered''','P0001','LEDGER_IMMUTABLE','Ledger cannot be edited');
select throws_ok('delete from public.ledger_entries','P0001','LEDGER_IMMUTABLE','Ledger cannot be deleted');
select throws_ok($$select public.change_member('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','MEMBER',true)$$,'P0001','SOLE_OWNER','Only owner cannot be demoted');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000005',true);
select throws_ok($$select public.post_financial('20000000-0000-0000-0000-000000000001','{"type":"TRANSFER","idempotency_key":"30000000-0000-0000-0000-000000000001"}')$$,'P0001','PERMISSION_DENIED','Viewer cannot post');
set local role authenticated;
select is((select count(*)::integer from public.projects where id='20000000-0000-0000-0000-000000000002'),0,'Viewer cannot see unrelated project');
select is((select count(*)::integer from public.financial_events where project_id='20000000-0000-0000-0000-000000000002'),0,'Other project ledger hidden');
reset role;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select throws_ok($$select public.change_member('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000003','OWNER',true)$$,'P0001','PERMISSION_DENIED','Member cannot escalate');
select throws_ok($$select public.project_summary('20000000-0000-0000-0000-000000000002')$$,'P0001','PERMISSION_DENIED','RPC prevents cross-project access');
select * from finish();
rollback;
